"""Author B1–C2 situations that fill the missing weeks in Danish and Luxembourgish.

These are new, independent dialogues, reading notices, written models and
contextual vocabulary — one distinct professional or civic situation per week,
not permutations of the existing scenes. Each unit carries an explicit
``course_week`` so it slots into the gap between the five seed units of its
level without shifting them. Every scene is marked
``pendiente de revisión por hablante competente``: native-speaker review and
student piloting are still required before any week is called validated.

Run: python3 scripts/build-upper-expansion.py
Output: content/upper-expansion.json
"""
import json
import random
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

# Each TOPICS entry: week, level, title, can-do goal, reading question,
# three answers (correct first), writing task.
TOPICS = []
# Per language: week -> (four alternating dialogue lines [(text, es)],
# independent reading notice, written model, two lexical chunks [(text, es)]).
LB = {}
DA = {}


def unit(week, level, title, goal, question, answers, writing, lb, da):
    TOPICS.append((week, level, title, goal, question, answers, writing))
    LB[week] = lb
    DA[week] = da


# =====================================================================
# B1 — Independencia (weeks 45–80). Seeds live at 45, 50, 55, 60, 65.
# Fill the other 31 weeks: narrate past/future, plans that change, work
# experience, cause and consequence, justified preferences, complaints,
# appointments, errands, local news, and cross-cutting workplace language.
# =====================================================================

unit(
    46, "B1", "Contar cómo fue el fin de semana",
    "Narra en pasado una actividad y di si te gustó.",
    "¿Qué hizo la persona el sábado?", ["Fue de excursión", "Se quedó en casa", "Trabajó"],
    "Cuenta en tres frases qué hiciste el fin de semana pasado.",
    ([("Wéi war däi Weekend?", "¿Qué tal tu fin de semana?"),
      ("E Samschdeg sinn ech wandere gaangen.", "El sábado fui de excursión."),
      ("A wéi war et?", "¿Y qué tal fue?"),
      ("Richteg schéin, mee ech war owes midd.", "Muy bonito, pero por la noche estaba cansado.")],
     "D'lescht Woch war d'Wieder gutt. Vill Leit si wandere gaangen an hunn de Weekend dobausse verbruecht.",
     "Mäi Weekend war roueg. E Samschdeg sinn ech wandere gaangen an e Sonndeg hunn ech mech ausgeruut.",
     [("wandere goen", "ir de excursión"), ("midd", "cansado")]),
    ([("Hvordan var din weekend?", "¿Qué tal tu fin de semana?"),
      ("Lørdag var jeg ude at vandre.", "El sábado fui de excursión."),
      ("Og hvordan var det?", "¿Y qué tal fue?"),
      ("Rigtig dejligt, men jeg var træt om aftenen.", "Muy bonito, pero por la noche estaba cansado.")],
     "Sidste uge var vejret godt. Mange var ude at vandre og tilbragte weekenden udendørs.",
     "Min weekend var rolig. Lørdag var jeg ude at vandre, og søndag slappede jeg af.",
     [("at vandre", "ir de excursión"), ("træt", "cansado")]),
)

